import {PLAYER_X,BIOMES,playerBox,obstacleBoxes} from './engine.js';
import {SPRITES} from './sprites.js';
import {headCutout} from './heads.js';
const images=new Map();let onLoad=()=>{};
export function asset(src){if(images.has(src))return images.get(src);const im=new Image();images.set(src,im);im.onload=()=>onLoad();im.onerror=()=>{im.failed=true;onLoad()};im.src=src;return im}
const ready=im=>im&&im.complete&&im.naturalWidth&&!im.failed;
const mix=(a,b,t)=>{const A=a.match(/\w\w/g).map(x=>parseInt(x,16)),B=b.match(/\w\w/g).map(x=>parseInt(x,16));return`rgb(${A.map((x,i)=>Math.round(x+(B[i]-x)*t)).join(',')})`};
export function createRenderer(canvas){
 const ctx=canvas.getContext('2d'),jungle=asset('assets/jungle-v2.webp'),bodies=asset('assets/body-atlas.webp'),objects=asset('assets/obstacles-atlas.webp');let current=null;
 const redraw=()=>current&&draw(...current);onLoad=redraw;
 function tile(im,index,x,y,w,h){if(!ready(im)||index<0)return false;const frames=im===bodies?SPRITES.body:SPRITES.obstacles,[cx,cy,cw,ch]=frames[index];ctx.drawImage(im,cx,cy,cw,ch,x,y,w,h);return true}
 function drawHead(im,x,y,size,rotation=0){if(!ready(im))return false;ctx.save();ctx.translate(x+size/2,y+size*.7);ctx.rotate(rotation);const cut=headCutout(im);if(cut){const ratio=cut.w/cut.h,w=size*ratio;ctx.drawImage(cut.image,cut.x,cut.y,cut.w,cut.h,-w/2,-size*.7,w,size)}else ctx.drawImage(im,im.width*.08,0,im.width*.84,im.height*.74,-size/2,-size*.7,size,size);ctx.restore();return true}
 function sky(w,h,run){const now=BIOMES[(run.stage-1)%BIOMES.length],prev=BIOMES[(run.stage-2+BIOMES.length)%BIOMES.length],blend=run.stage===1?1:Math.min(1,(run.time%30)/4),top=mix(prev[1],now[1],blend),bottom=mix(prev[2],now[2],blend),g=ctx.createLinearGradient(0,0,0,h);g.addColorStop(0,top);g.addColorStop(1,bottom);ctx.fillStyle=g;ctx.fillRect(0,0,w,h);
  if(ready(jungle)){const sh=h*1.08,sw=jungle.width/jungle.height*sh,off=(run.distance*4.2)%(sw*2);ctx.save();ctx.globalAlpha=.56;ctx.globalCompositeOperation='multiply';for(let i=-1;i<4;i++){ctx.save();ctx.translate(i*sw-off+(i%2?0:sw),-h*.02);if(i%2===0)ctx.scale(-1,1);ctx.drawImage(jungle,0,0,sw,sh);ctx.restore()}ctx.restore()}
  // Three slow parallax layers retain obstacle contrast while making the world move.
  for(let layer=0;layer<3;layer++){ctx.save();ctx.globalAlpha=.11+layer*.05;ctx.fillStyle=layer===0?'#d9fff0':'#071d22';const off=(run.distance*(2+layer*3))%(180+layer*35);for(let x=-220;x<w+220;x+=180+layer*35){const xx=x-off;ctx.beginPath();ctx.arc(xx,h*(.25+layer*.17),28+layer*15,0,Math.PI*2);ctx.fill()}ctx.restore()}
  if(run.stage%8===5){ctx.fillStyle='#dfe6ff';ctx.globalAlpha=.65;ctx.beginPath();ctx.arc(w*.8,h*.17,34,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
  if(run.event?.name==='MONSOON'||run.stage%8===6){ctx.strokeStyle='#c6e9ff';ctx.globalAlpha=.22;for(let i=0;i<40;i++){const x=(i*73+run.time*180)%(w+60)-30,y=(i*47+run.time*260)%(h*.8);ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-8,y+20);ctx.stroke()}ctx.globalAlpha=1}
  if(run.event?.name==='BOULDER CHASE'){ctx.fillStyle='#26332d';ctx.globalAlpha=.72;ctx.beginPath();ctx.arc(38,h*.72,58,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
  if(run.event?.name==='STAMPEDE'){ctx.fillStyle='#172b22';ctx.globalAlpha=.48;for(let i=0;i<5;i++){const x=(w+180-i*110-run.time*70)%(w+350)-80,y=h*(.62+(i%2)*.04);ctx.beginPath();ctx.ellipse(x,y,31,16,0,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
  if(run.event?.name==='TEMPLE COLLAPSE'){ctx.fillStyle='#725f43';ctx.globalAlpha=.35;for(let i=0;i<6;i++){const x=w*.58+i*42,y=(run.time*35+i*31)%(h*.55);ctx.save();ctx.translate(x,y);ctx.rotate(run.time+i);ctx.fillRect(-9,-9,18,18);ctx.restore()}ctx.globalAlpha=1}
 }
 function ground(vw,h,run){const biome=(run.stage-1)%8,g=ctx.createLinearGradient(0,0,0,110);g.addColorStop(0,biome===6?'#4b2e27':'#36503a');g.addColorStop(.22,biome===3?'#6c6543':'#273e31');g.addColorStop(1,'#14271f');ctx.fillStyle=g;ctx.fillRect(0,0,vw,h);ctx.fillStyle=biome===2?'#9cc9a8':'#78a45e';ctx.fillRect(0,0,vw,5);
  const offset=(run.distance*100)%74;for(let i=-1;i<18;i++){const x=i*74-offset,y=12+(i%3)*10;ctx.fillStyle=i%2?'#526549':'#263d32';ctx.beginPath();ctx.ellipse(x,y,19,7,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#8cb16a';ctx.beginPath();ctx.moveTo(x+11,1);ctx.lineTo(x+15,-7-(i%4)*2);ctx.stroke()}
 }
 function obstacle(o){if(o.tile>=0&&tile(objects,o.tile,o.x-8,-o.h-9,o.w+16,o.h+14))return;ctx.save();if(o.family==='wide'){if(o.id==='puddle'){ctx.fillStyle='#56a8c7';ctx.beginPath();ctx.ellipse(o.x+o.w/2,-5,o.w/2,10,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#b8eff5';ctx.stroke()}else if(o.id==='ravine'){ctx.fillStyle='#071310';ctx.fillRect(o.x,-10,o.w,16);ctx.fillStyle='#b47039';for(let i=0;i<o.w;i+=28)ctx.fillRect(o.x+i,-14,16,5)}else{ctx.fillStyle='#d0c15e';for(let i=0;i<o.w;i+=14){ctx.beginPath();ctx.moveTo(o.x+i,0);ctx.lineTo(o.x+i+7,-26);ctx.lineTo(o.x+i+14,0);ctx.fill()}}}
  else {ctx.fillStyle=o.id==='temple-beam'?'#857353':'#506a32';ctx.fillRect(o.x,-76,o.w,24);ctx.fillStyle='#314822';for(let i=0;i<o.w;i+=20)ctx.fillRect(o.x+i,-52,6,16+(i%3)*5)}ctx.restore()}
 function character(state,run,selected){const im=asset(selected.head||selected.image),sliding=run.y===0&&(run.slideTime>0||run.slideHeld||run.slideBlocked),frame=state==='over'?7:sliding?7:run.y>0?(run.vy>70?5:6):run.landing>0?7:state==='running'?Math.floor(run.time*(9+run.speed/85))%4:4,bf=SPRITES.body[frame],necks=[[240,168],[596,160],[988,160],[1384,168],[210,645],[584,596],[944,650],[1380,724]],neck=necks[frame],bs=.22;
  const bob=!sliding&&run.y===0&&state==='running'?Math.sin(run.time*24)*1.2:0,rot=sliding?-.18:run.vy>0?-.04:run.vy<0?.035:0;ctx.save();ctx.translate(PLAYER_X+(run.shake?Math.sin(run.time*110)*3:0),-run.y+bob);ctx.rotate(rot);if(run.shield||run.invulnerable>0){ctx.strokeStyle=run.shield?'#a5ffe4':'#fff2a2';ctx.lineWidth=3;ctx.globalAlpha=.65+.25*Math.sin(run.time*30);ctx.beginPath();ctx.ellipse(sliding?8:0,sliding?-25:-49,sliding?52:43,sliding?28:58,0,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}
  let bx=-(neck[0]-bf[0])*bs,by=-bf[3]*bs;if(sliding){ctx.translate(8,3);ctx.rotate(-.12);bx-=7;by+=16}tile(bodies,frame,bx,by,bf[2]*bs,bf[3]*bs);const headY=by+(neck[1]-bf[1])*bs-(sliding?44:51);if(!drawHead(im,-28,headY,56,sliding?.12:0)){ctx.fillStyle='#e4e984';ctx.font='36px monospace';ctx.textAlign='center';ctx.fillText('?',0,-58)}if(run.modeTime>0){ctx.globalAlpha=.18;ctx.fillStyle='#f8ed72';for(let i=1;i<5;i++)ctx.fillRect(-i*13,-55+i*3,8,35);ctx.globalAlpha=1}ctx.restore()}
 function draw(state,run,selected,particles=[]){current=[state,run,selected,particles];if(!ctx)return;const w=canvas.width,h=canvas.height;if(!w||!h)return;const active=['running','countdown','paused','over'].includes(state),vw=Math.max(600,Math.min(1080,w/h*500)),scale=w/vw,groundY=h*.83;ctx.clearRect(0,0,w,h);ctx.imageSmoothingEnabled=false;sky(w,h,run);ctx.save();ctx.translate(0,groundY);ctx.scale(scale,scale);ground(vw,h/scale,run);
  if(active){for(const o of run.obstacles)obstacle(o);for(const b of run.bananas){if(b.golden){ctx.save();ctx.shadowColor='#fff59a';ctx.shadowBlur=15;ctx.fillStyle='#ffe13d';ctx.beginPath();ctx.ellipse(b.x,-b.y,11,17,-.45,0,Math.PI*2);ctx.fill();ctx.restore()}else if(!tile(objects,7,b.x-15,-b.y-15,30,30)){ctx.font='24px serif';ctx.fillText('🍌',b.x,-b.y)}}if(run.power){ctx.font='30px serif';ctx.textAlign='center';ctx.fillText('🛡️',run.power.x,-run.power.y+12)}character(state,run,selected);
   for(const p of particles){ctx.globalAlpha=Math.min(1,p.life/.4);ctx.fillStyle=p.color||'#d0dca0';if(p.label){ctx.font='bold 18px monospace';ctx.fillText(p.label,p.x,-p.y)}else ctx.fillRect(p.x,-p.y,p.size||4,p.size||4)}ctx.globalAlpha=1;
   if(run.debug){ctx.strokeStyle='#ff4d7d';const p=playerBox(run);ctx.strokeRect(p.x,p.y*-1-p.h,p.w,p.h);ctx.strokeStyle='#ffe45f';for(const o of run.obstacles)for(const b of obstacleBoxes(o))ctx.strokeRect(b.x,-b.y-b.h,b.w,b.h)}
  }ctx.restore();if(run.event){ctx.fillStyle='#e8f6dc';ctx.globalAlpha=.65;ctx.font=`${Math.max(12,w/85)}px monospace`;ctx.textAlign='right';ctx.fillText(run.event.name,w-24,h*.19);ctx.globalAlpha=1}}
 function resize(){try{const r=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.round(r.width*dpr));canvas.height=Math.max(1,Math.round(r.height*dpr));redraw()}catch{}}
 return{draw,resize}
}
